dict.string:
.navbar {
	font-family: 'Helvetica Neue', Arial, sans-serif;
	font-size: .8em;
	color: #666666;
	line-height: 30px;
	border-bottom: 3px solid #ccc;
}

.navbar-bg {
	text-align: right;}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0px 5px 0px 0px;
}


li a {
	text-decoration: none;
	padding: 10px;
	color: #666666;
	font-weight: bold;
}

li a:visited {
	text-decoration: none;
	padding: 10px;
	color: #666666;
	font-weight: bold;
}

li a:hover{
 	color: #999999;
	text-decoration: none;}


li.current-page a{	 color: #66ABC5;
	text-decoration: none;}
